bounded_host_request.command:
python3 -c 'import subprocess,json
retire=["ai-granite","ai-ministral"]
preserve=["ai-qwen3","ai-coder"]
p=subprocess.run(["docker","inspect"]+retire+preserve,capture_output=True,text=True,timeout=10,check=True)
d={x["Name"].lstrip("/"):x for x in json.loads(p.stdout)}
assert len(d)==4 and all(d[n]["State"]["Running"] for n in d)
for n in retire:
 r=subprocess.run(["docker","stop","--timeout","25",n],capture_output=True,text=True,timeout=40)
 print("STOP_"+n+"="+str(r.returncode))
 if r.returncode: raise SystemExit(1)
p=subprocess.run(["docker","inspect"]+retire+preserve,capture_output=True,text=True,timeout=10,check=True)
v={x["Name"].lstrip("/"):x["State"]["Running"] for x in json.loads(p.stdout)}
for n in retire+preserve: print("RUNNING_"+n+"="+str(v[n]))
assert all(not v[n] for n in retire) and all(v[n] for n in preserve)
print("TWO_RESIDENT_CUTOVER=PASS")
'
